function UIFishPoolGoFishingDialog3:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CriWareUtils.RemoveCueSheet(UISheets.SFX_Fishing.path)

        if not isNull(self._behaviourAction) then
            self._behaviourAction.UpdateAction = nil
        end
        CfUtils.SetTopActive(true)
        if not IsNull(ScreenTouchEffectModule) then
            KTool.SetActive(ScreenTouchEffectModule.Instance.gameObject, true)
        end

        if FishingMgr:GetInstance()._ganGo then
            CS.UnityEngine.GameObject.Destroy(FishingMgr:GetInstance()._ganGo)
        end

        if self.CoClick then
            --避免界面卡死
            UIRaycastBlocker:RemoveCondition("UIFishPoolGoFishingDialogFinish")
            cs_coroutine.stop(self.CoClick)
        end

        if self.CoTalk then
            cs_coroutine.stop(self.CoTalk)
        end

        if self.CoRemindTipHide then
            cs_coroutine.stop(self.CoRemindTipHide)
        end

        if self.eventDic then
            for name, handler in ipairs(self.eventDic) do
                Events.RemoveListener(name, handler)
            end
        end

        UIFishPoolGoFishingDialog3.states[EGoFishState.Ready]:Delete()
        UIFishPoolGoFishingDialog3.states[EGoFishState.Fishing]:Delete()

        self.autoFishPanelServer:KillCo()

        Events.RemoveListener(Constants.EventNames.FishActivityCurrencyChange, self.fishConsumeBuyHandler)

        if self.clearScene then
            cs_coroutine.yield_return(FishingMgr:GetInstance():Clear())
        end

        self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

