function UIFishPoolGoFishingDialog3.TransferTo(target, params)
    if UIFishPoolGoFishingDialog3.curState and UIFishPoolGoFishingDialog3.states[target] and not UIFishPoolGoFishingDialog3.curState:CanTransfer(target) then
        return
    end

    if not isNull(UIFishPoolGoFishingDialog3.curState) then
        UIFishPoolGoFishingDialog3.curState:OnExit()
    end

    UIFishPoolGoFishingDialog3.curState = UIFishPoolGoFishingDialog3.states[target]
    UIFishPoolGoFishingDialog3.curState:OnEnter(params)
end

function UIFishPoolGoFishingDialog3:Awake()
    self.argument = self.controller.Argument.parameters
    if isNull(self.argument) then return end

    if not IsNull(ScreenTouchEffectModule) then
        KTool.SetActive(ScreenTouchEffectModule.Instance.gameObject, false)
    end

    if isNull(self._behaviourAction) then
        self._behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
        self._behaviourAction.UpdateAction = function()
            self:OnUpdate()
        end
    end

    self.placeId = self.argument.fishingPlaceId
    self.goodsVo = checkTable(self.argument.goodsVo)
    if self.goodsVo.jumpParameter then
        self.targetFishId = checkNumber(self.goodsVo.jumpParameter[1])    --目标鱼id
    end
    if not self.targetFishId then
        self._showOnlyFish = true
        self.targetFishId = checkNumber(self.goodsVo.openParameter)
    end
    self.placeVo = FishingUtils.GetFishingPlaceVo(self.placeId)
    if isNull(self.placeVo) then return end
    self.sceneId = checkString(self.placeVo.sceneId)

    --- 服务层对象
    self.topGoodsServer         = GoFishingServiceFactory.Create(self, GoFishingServiceType.TopGoodsService)
    self.placeNameServer        = GoFishingServiceFactory.Create(self, GoFishingServiceType.PlaceNameService)
    self.roleAnimServer         = GoFishingServiceFactory.Create(self, GoFishingServiceType.RoleAnimService)
    self.fishingGoodsServer     = GoFishingServiceFactory.Create(self, GoFishingServiceType.FishingGoodsService)
    self.btnLeaveServer         = GoFishingServiceFactory.Create(self, GoFishingServiceType.BtnLeaveService)
    self.btnFishingGroupServer  = GoFishingServiceFactory.Create(self, GoFishingServiceType.BtnFishingGroupService)
    self.leftPanelServer        = GoFishingServiceFactory.Create(self, GoFishingServiceType.LeftPanelService)
    self.throwPoleServer        = GoFishingServiceFactory.Create(self, GoFishingServiceType.ThrowPoleService)
    self.startFishingServer     = GoFishingServiceFactory.Create(self, GoFishingServiceType.StartFishingService)
    self.btnFishAtlasServer     = GoFishingServiceFactory.Create(self, GoFishingServiceType.BtnFishAtlasService)
    self.fishDisplayServer      = GoFishingServiceFactory.Create(self, GoFishingServiceType.FishDisplayService)
    self.damageBarServer        = GoFishingServiceFactory.Create(self, GoFishingServiceType.DamageBarService)
    self.fishBloodServer        = GoFishingServiceFactory.Create(self, GoFishingServiceType.FishBloodService)
    self.operationTipServer     = GoFishingServiceFactory.Create(self, GoFishingServiceType.OperationTipService)
    self.fishLineServer         = GoFishingServiceFactory.Create(self, GoFishingServiceType.FishLineService)
    self.autoFishPanelServer    = GoFishingServiceFactory.Create(self, GoFishingServiceType.AutoFishPanelService)
    self.tipsServer             = GoFishingServiceFactory.Create(self, GoFishingServiceType.TipsService)

    --- 状态类
    UIFishPoolGoFishingDialog3.states[EGoFishState.Init]      = GoFishInitState.new(self)
    UIFishPoolGoFishingDialog3.states[EGoFishState.Ready]     = GoFishReadyState.New(self)
    UIFishPoolGoFishingDialog3.states[EGoFishState.Casting]   = GoFishCastingState.new(self)
    UIFishPoolGoFishingDialog3.states[EGoFishState.Fishing]   = GoFishFishingState.New(self)
    UIFishPoolGoFishingDialog3.states[EGoFishState.End]       = GoFishEndState.new(self)
end

function UIFishPoolGoFishingDialog3:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetTopCommonCb(function()
            if not FishingUtils.IsAutoing() then
                self.clearScene = true
                UIModule.BackDialog()
            end
        end)

        SetButtonAction(self.BtnFishNet, Bind(self, self.OnClickFishNetHandler))

        SceneManagement:GetInstance():SetActive(FishingMgr:GetInstance():GetCurFishSceneId(), true)

        local go = GameUtils.GetRedPointGo(self.BtnFishAtlas)
        local num = redPointCom:GetNodeNum(Constants.RedPointConst["PhoneFishCollection" .. self.placeId])
        CfUtils.SetActive(go, num > 0)

        --- 设置买完钓鱼券的回调函数
        self.fishConsumeBuyHandler = Events.AddListener(Constants.EventNames.FishActivityCurrencyChange, Bind(self, self.OnCurrencyChanged))

        --- 初始状态为init
        UIFishPoolGoFishingDialog3.TransferTo(EGoFishState.Init)

    end))
    return coWait
end

function UIFishPoolGoFishingDialog3:OnCurrencyChanged()
    self.btnFishingGroupServer:UpdateInfo()
    self.fishingGoodsServer:UpdateInfo()
end

function UIFishPoolGoFishingDialog3:OnUpdate()
    if not isNull(self.curState) then
        self.curState:Update()
    end
end

