function UIFishPoolGoFishingDialog3:OnShow()

    local camGo = FishingMgr:GetInstance():GetSceneCam()
    if not isNull(camGo) then
        local urpBase = camGo:GetComponent(typeof(URPBaseCamera))
        urpBase:CopyCamera()
    end
end

function UIFishPoolGoFishingDialog3:OnCaptureAction()
    local effectBg = self.controller.gameObject:GetComponent(typeof(UIEffectCapturedImage))
    if effectBg then
        effectBg:Capture()
    end
end

function UIFishPoolGoFishingDialog3:OnHide()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.ResetNavigatorCustomBackAction()
        cs_coroutine.yield_return(self:OnCaptureAction())


    end))
    return coWait
end

function UIFishPoolGoFishingDialog3:OnClickFishNetHandler()
    local goodsId = Constants.Currency.FishNetConsume
    local ownNum = GoodsUtils.GetThingNo(goodsId)
    local consumeCount = 1
    local isEnough = ownNum >= consumeCount

    if isEnough then
        UIModule.OpenDialog({
            id = Constants.UITypeIds.UIFastNettingFishDialog,
            parameters = {
                fishPlaceId = self.placeId,
                consumeGoodsId = goodsId,
                ownCount = ownNum,
                placeId = self.placeId,
                cb = function()
                    self.btnFishAtlasServer:UpdateInfo()
                    CfUtils.SetActive(self.Container, true)
                end
            }
        }, {
            --{ id = Constants.UITypeIds.UIFishPoolGoFishingDialog }
        })
        CfUtils.SetActive(self.Container, false)
    else
        GoodsUtils.ShowCommonLackMaterialDialog({{goodsId = goodsId, num = 1}})
    end
end

return UIFishPoolGoFishingDialog3